extern int32_t bb_is_debug(void);

// The names that earlier versions read. "inverted" is for the NO_ switches, whose value meant the opposite of the new switch.
struct alias {
	const char* name;
	const char* old;
	int         inverted;
	int         used;
	int         warned;
};

