static void warn(struct alias* a)
{
	if (a->warned) {
		return;
	}
	a->warned = 1;
	fprintf(stderr, "warning: the environment variable %s is deprecated, use %s%s instead\n", a->old, a->name, a->inverted ? " (with the opposite value)" : "");
}

void bb_env_report_deprecated(void)
{
	if (!bb_is_debug()) {
		return;
	}
	for (size_t index = 0; index < sizeof(aliases) / sizeof(aliases[0]); index++) {
		if (aliases[index].used) {
			warn(&aliases[index]);
		}
	}
}

#if defined(_WIN32)
#define environ _environ
#endif
extern char** environ;

// The BLITZLLVM_ and BLITZ_ variables as they were when the program started. A program that changes the environment with SetEnv does
// not change how the runtime behaves, only what GetEnv and the programs it starts see.
#define LIVE_ENV "BLITZLLVM_TEST_LIVE_ENV" // Read before the snapshot exists, so not through bb_env.
// Static storage: the allocator of the runtime reads its settings through here, so this can't allocate.
#define SNAPSHOT_MAX_ENTRIES 256
#define SNAPSHOT_MAX_BYTES   32768
static const char* snapshot[SNAPSHOT_MAX_ENTRIES];
static char        snapshot_text[SNAPSHOT_MAX_BYTES];
static size_t      snapshot_count = 0;
static int         snapshot_taken = 0;
static int         snapshot_live  = 0; // BLITZLLVM_TEST_LIVE_ENV=1 at the start: the test programs set the variables they test with SetEnv.

void bb_env_snapshot(void)
{
	if (snapshot_taken) {
		return;
	}
	snapshot_taken = 1;
	const char* live = getenv(LIVE_ENV);
	snapshot_live    = live && !strcmp(live, "1");
	size_t used      = 0;
	for (char** entry = environ; entry && *entry; entry++) {
		if (strncmp(*entry, "BLITZLLVM_", 10) && strncmp(*entry, "BLITZ_", 6)) {
			continue;
		}
		size_t length = strlen(*entry) + 1;
		if (snapshot_count >= SNAPSHOT_MAX_ENTRIES || used + length > SNAPSHOT_MAX_BYTES) {
			break;
		}
		memcpy(snapshot_text + used, *entry, length);
		snapshot[snapshot_count++] = snapshot_text + used;
		used += length;
	}
}

static const char* snapshot_get(const char* name)
{
	bb_env_snapshot();
	if (snapshot_live) {
		return getenv(name);
	}
	size_t length = strlen(name);
	for (size_t index = 0; index < snapshot_count; index++) {
		if (!strncmp(snapshot[index], name, length) && snapshot[index][length] == '=') {
			return snapshot[index] + length + 1;
		}
	}
	return NULL;
}

static const char* lookup(const char* name, int* inverted)
{
	*inverted = 0;
	const char* value = snapshot_get(name);
	if (value && *value) {
		return value;
	}
	for (size_t index = 0; index < sizeof(aliases) / sizeof(aliases[0]); index++) {
		struct alias* a = &aliases[index];
		if (strcmp(a->name, name) != 0) {
			continue;
		}
		value = snapshot_get(a->old);
		if (value && *value) {
			a->used = 1;
			if (bb_is_debug()) {
				warn(a);
			}
			*inverted = a->inverted;
			return value;
		}
		break;
	}
	return NULL;
}

const char* bb_env(const char* name)
{
	int inverted;
	return lookup(name, &inverted);
}

static int equals_ignoring_case(const char* a, const char* b)
{
	for (; *a && *b; a++, b++) {
		if (tolower((unsigned char)*a) != tolower((unsigned char)*b)) {
			return 0;
		}
	}
	return *a == *b;
}

static int is_false(const char* value)
{
	return !strcmp(value, "0") || equals_ignoring_case(value, "false") || equals_ignoring_case(value, "no") || equals_ignoring_case(value, "off");
}

int32_t bb_env_bool(const char* name, int32_t fallback)
{
	int         inverted;
	const char* value = lookup(name, &inverted);
	if (!value) {
		return fallback;
	}
	int result = !is_false(value);
	return inverted ? !result : result;
}

double bb_env_double(const char* name, double fallback)
{
	int         inverted;
	const char* value = lookup(name, &inverted);
	if (!value) {
		return fallback;
	}
	char*  end;
	double number = strtod(value, &end);
	return (end != value) ? number : fallback;
}

int32_t bb_env_int(const char* name, int32_t fallback)
{
	int         inverted;
	const char* value = lookup(name, &inverted);
	if (!value) {
		return fallback;
	}
	char* end;
	long  number = strtol(value, &end, 0);
	return (end != value) ? (int32_t)number : fallback;
}
